import {usbOptions} from './usb-core.js';
import {uid,defaults,calculate} from './core.js';
import {esc,btn,field,select} from './views.js';
import {saleBody} from './workshop-views.js';
import {PROFILE_KEYS,syncSupplyPrices,setPrinter,stockItem,recordSale,recordPurchase,voidTransaction,removeInventory,salePreview,recordAdjustment} from './workshop.js';
import * as storage from './storage.js';
export function workshopController(c){
 const {ui,render,persist,flush,showModal,closeModal,toast}=c,S=c.state,$=id=>document.getElementById(id),value=id=>$(id).value;
 let transactionBusy=false,probing=false;
 const dialogValid=()=>{if([...document.querySelectorAll('#modal-root input')].some(i=>!i.checkValidity()))throw Error('Revisa los campos del formulario.');};
 async function commit(fn){if(transactionBusy)return;transactionBusy=true;const snapshot=structuredClone(S());try{fn();await flush();closeModal();render();toast('Movimiento guardado. Inventario actualizado.');}catch(e){c.setState(snapshot);render();throw e;}finally{transactionBusy=false;}}
 function supplyDialog(id){const m=S().supplies.find(x=>x.id===id)||{id:uid(),name:'',unit:'pzas',stock:0,minStock:10,unitCost:1,packUnits:100};showModal(id?'Editar insumo':'Nuevo insumo compartido',`<div class="form-grid">${field('Nombre',m.name,'id="supply-name" required','text')}${select('Unidad',[['pzas','Piezas'],['g','Gramos'],['ml','Mililitros'],['m','Metros']],m.unit,'id="supply-unit"')}${field('Existencias contadas',m.stock,'id="supply-stock"')}${field('Avisar al quedar esta cantidad',m.minStock,'id="supply-min"')}${field('Costo por unidad',m.unitCost,'id="supply-cost"')}${field('Unidades por paquete completo',m.packUnits,'id="supply-pack" min="0.001"')}</div><p class="short-note">Usa la misma unidad para las existencias y el consumo por objeto. Ejemplo: botella de 250 ml, 2 ml por figura. Este formulario corrige el conteo; registra las compras en «Registrar compra» para descontar su importe del saldo.</p>`,btn('Cancelar','close-modal')+btn('Guardar','save-supply','check','primary',`data-id="${esc(m.id)}"`));}
 function purchaseDialog(kind,id){const options=[...S().materials.filter(m=>!m.retired).map(m=>[`material:${m.id}`,'Filamento · '+m.name]),...S().supplies.filter(m=>!m.retired).map(m=>[`supply:${m.id}`,'Insumo · '+m.name])];if(!options.length)throw Error('Agrega primero un filamento o insumo.');const key=kind&&id?`${kind}:${id}`:options[0][0],[k,i]=key.split(':'),m=stockItem(S(),k,i),units=k==='material'?m.spoolGrams:m.packUnits;showModal('Registrar compra de material',`<div class="form-grid">${select('Artículo',options,key,'id="purchase-item"')}${field('Paquetes o bobinas',1,'id="purchase-packs" min="1" step="1"')}${field(k==='material'?'Gramos por bobina':`Contenido por paquete (${m.unit})`,units,'id="purchase-units" min="0.001"')}${field('Importe total pagado',k==='material'?m.price:m.unitCost*units,'id="purchase-total"')}${field('Referencia / proveedor / nota','','id="purchase-note"','text')}</div><p class="short-note">El total pagado se descontará del saldo del taller y se agregará todo el contenido al inventario. Si cambias la cantidad de paquetes, revisa el importe total: incluye envío y descuentos. El precio para cotizar se edita en el artículo.</p>`,btn('Cancelar','close-modal')+btn('Registrar compra','confirm-purchase','check','primary'));}
 function showSale(){let disabled=true;try{disabled=!!salePreview(S(),ui.cart,ui.saleReserve!==false).shortages.length;}catch{}showModal('Registrar una venta',saleBody(S(),ui),btn('Cancelar','close-modal')+btn('Confirmar venta y descontar stock','confirm-sale','check','primary',disabled?'disabled':''));}
 function deleteDialog(kind,id){const item=stockItem(S(),kind,id);ui.deleteStock={kind,id};const options=(kind==='material'?S().materials:S().supplies).filter(x=>x.id!==id&&!x.retired);showModal('Eliminar '+item.name,`<p>Si se usa en objetos, elige un reemplazo o deja su asignación pendiente. No se transfieren existencias al reemplazo. Los filamentos sustituidos necesitan volver a laminarse. Si tiene ventas o compras, se retira de las listas y se conserva el historial.</p>${select('Reemplazo para los objetos',[['','Sin reemplazo (solo si no se utiliza)'],['__none__','Dejar pendiente de asignación en los objetos'],...options.map(x=>[x.id,x.name])],'','id="stock-replacement"')}`,btn('Cancelar','close-modal')+btn('Eliminar del inventario','confirm-delete-stock','trash','danger'));}
 async function probe(){if(probing||!storage.isNative)return;probing=true;try{const r=await storage.api('printers',{printers:S().printers.map(p=>({id:p.id,connection:p.connection,deviceId:p.usbManual?'serial:'+String(p.usbPort||'').toUpperCase():p.deviceId,host:p.host,port:p.port}))});ui.devices=r.devices||[];let migrated=false;for(const p of S().printers){if(p.usbManual)continue;const d=ui.devices.find(d=>d.hardwareId&&d.hardwareId.toLowerCase()===String(p.deviceId||'').toLowerCase());if(d){p.deviceId=d.id;p.usbPort=d.port;migrated=true;}}if(migrated)persist();ui.printerStatus=r.statuses||{};ui.probeTime='Comprobado: '+new Date(r.checkedAt).toLocaleTimeString('es-MX')+(r.note?' · '+r.note:'');for(const el of document.querySelectorAll('[data-printer-status]')){const st=ui.printerStatus[el.dataset.printerStatus];el.textContent=st?.message||'Sin comprobar';el.classList.toggle('online',!!st?.connected);}document.querySelector('[data-probe-time]')?.replaceChildren(document.createTextNode(ui.probeTime));
 const input=document.querySelector('[data-connection="deviceId"],#print-device');if(input&&document.activeElement!==input){const active=S().printers.find(p=>p.id===S().activePrinterId);const options=input.id==='print-device'?usbOptions(ui.devices,active):[['','Elige el dispositivo conectado'],...ui.devices.map(d=>[d.id,`${d.name} ${d.port||''}`])];input.innerHTML=options.map(([id,n])=>`<option value="${esc(id)}" ${id===(input.id==='print-device'&&active?.usbManual?'__manual__':active?.deviceId)?'selected':''}>${esc(n)}</option>`).join('');}
 }catch(e){ui.printerStatus={};ui.probeTime='No se pudo comprobar: '+e.message;for(const el of document.querySelectorAll('[data-printer-status]')){el.textContent='Estado desconocido · consulta fallida';el.classList.remove('online');}}finally{probing=false;}}
 const actions={
 'new-supply':()=>supplyDialog(),'edit-supply':el=>supplyDialog(el.dataset.id),
 'save-supply':el=>{dialogValid();const name=value('supply-name').trim();if(!name)throw Error('Escribe el nombre del insumo.');const item={id:el.dataset.id,name,unit:value('supply-unit'),stock:+value('supply-stock'),minStock:+value('supply-min'),unitCost:+value('supply-cost'),packUnits:+value('supply-pack')};const n=S().supplies.findIndex(x=>x.id===item.id),stock=item.stock;item.stock=n>=0?S().supplies[n].stock:0;if(n>=0)S().supplies[n]=item;else S().supplies.push(item);recordAdjustment(S(),'supply',item.id,stock,n>=0?'Ajuste de conteo':'Conteo inicial');syncSupplyPrices(S());closeModal();persist();render();},
 'assign-supply':()=>{const list=S().supplies.filter(x=>!x.retired);if(!list.length){toast('Agrega primero un insumo en Inventario.');ui.view='inventory';ui.inventoryTab='supplies';render();supplyDialog();return;}showModal('Asignar insumo a este objeto',`${select('Insumo del inventario',list.map(x=>[x.id,`${x.name} · ${x.unit}`]),list[0].id,'id="extra-supply"')}${field('Unidades consumidas por objeto',1,'id="extra-units" min="0.001"')}`,btn('Cancelar','close-modal')+btn('Asignar','confirm-assign-supply','check','primary'));},
 'confirm-assign-supply':()=>{dialogValid();const item=S().supplies.find(x=>x.id===value('extra-supply'));c.object().extras.push({id:uid(),supplyId:item.id,name:item.name,qty:+value('extra-units'),price:item.unitCost});closeModal();persist();render();},
 'purchase':el=>purchaseDialog(el.dataset.kind,el.dataset.id),
 'confirm-purchase':()=>{dialogValid();const [kind,id]=value('purchase-item').split(':');const input={kind,id,packs:+value('purchase-packs'),packUnits:+value('purchase-units'),total:+value('purchase-total'),note:value('purchase-note')};return commit(()=>recordPurchase(S(),input));},
 'new-sale':()=>{ui.cart=[];ui.saleReserve=true;ui.saleNote='';showSale();},
 'add-sale-line':()=>{dialogValid();const [boxId,objectId]=value('sale-object').split('|'),o=S().boxes.find(b=>b.id===boxId)?.objects.find(o=>o.id===objectId),qty=+value('sale-qty');if(!o)throw Error('Agrega primero un objeto en tu estantería.');const calc=calculate(o,S().materials,S().settings,qty,o.multiplier);const existing=ui.cart.find(l=>l.boxId===boxId&&l.objectId===objectId);if(existing){existing.qty+=qty;existing.unitPrice=Math.round(calculate(o,S().materials,S().settings,existing.qty,o.multiplier).price*100)/100;}else ui.cart.push({boxId,objectId,name:o.name,qty,unitPrice:Math.round(calc.price*100)/100});ui.saleNote=value('sale-note');showSale();},
 'remove-sale-line':el=>{ui.cart.splice(+el.dataset.index,1);showSale();},
 'confirm-sale':()=>{dialogValid();const note=value('sale-note');return commit(()=>recordSale(S(),ui.cart,{reserve:ui.saleReserve!==false,note}));},
 'void-transaction':el=>{ui.voidId=el.dataset.id;showModal('Anular movimiento','<p>Se revertirá el movimiento de stock y su importe. El registro permanecerá marcado como anulado. Una compra solo puede anularse si sus unidades siguen disponibles.</p>',btn('Cancelar','close-modal')+btn('Anular movimiento','confirm-void','back','danger'));},
 'confirm-void':()=>commit(()=>voidTransaction(S(),ui.voidId)),
 'delete-material':el=>deleteDialog('material',el.dataset.id),'delete-supply':el=>deleteDialog('supply',el.dataset.id),
 'confirm-delete-stock':()=>{removeInventory(S(),ui.deleteStock.kind,ui.deleteStock.id,value('stock-replacement'));closeModal();persist();render();toast('Artículo retirado del inventario activo.');},
 'restore-stock':el=>{stockItem(S(),el.dataset.kind,el.dataset.id).retired=false;persist();render();},
 'new-printer':()=>showModal('Agregar una impresora',`${field('Nombre / modelo','','id="printer-name" required','text')}<p>Se creará un perfil con valores iniciales editables. Configura después su cama, consumo y conexión.</p>`,btn('Cancelar','close-modal')+btn('Crear perfil','create-printer','plus','primary')),
 'create-printer':()=>{const name=value('printer-name').trim();if(!name)throw Error('Escribe el nombre de la impresora.');if(S().printers.length>=32)throw Error('El máximo es 32 perfiles.');const d=defaults().settings,p={id:uid(),...Object.fromEntries(PROFILE_KEYS.map(k=>[k,d[k]])),printer:name,connection:'none',deviceId:'',host:'',port:80};S().printers.push(p);setPrinter(S(),p.id);closeModal();persist();render();},
 'use-printer':el=>{setPrinter(S(),el.dataset.id);persist();render();probe();},
 'delete-printer':el=>{if(S().printers.length===1)throw Error('Conserva al menos un perfil para calcular costos.');ui.deletePrinter=el.dataset.id;showModal('Eliminar perfil de impresora','<p>Se eliminará este perfil. Las cotizaciones y ventas ya registradas conservarán sus importes.</p>',btn('Cancelar','close-modal')+btn('Eliminar perfil','confirm-delete-printer','trash','danger'));},
 'confirm-delete-printer':()=>{S().printers=S().printers.filter(p=>p.id!==ui.deletePrinter);if(S().activePrinterId===ui.deletePrinter)setPrinter(S(),S().printers[0].id);closeModal();persist();render();},
 'probe-printers':async()=>{await probe();toast(ui.probeTime||'Comprobación terminada.');},
 'delete-box':()=>showModal('Eliminar esta caja',`<p>«${esc(c.box().name)}» se quitará de la estantería. Su carpeta completa se moverá a la papelera local de 3D-Woods. Las ventas registradas conservarán su historial.</p>`,btn('Cancelar','close-modal')+btn('Mover a la papelera','confirm-delete-box','trash','danger')),
 'confirm-delete-box':async()=>{if(transactionBusy)return;transactionBusy=true;try{await flush();const b=c.box();if(b.folder)await storage.api('trash-box',{id:b.id,folder:b.folder});S().boxes=S().boxes.filter(x=>x.id!==b.id);ui.selected=null;ui.picked=false;ui.view='shelf';await flush();closeModal();render();toast('Caja eliminada de la estantería.');}finally{transactionBusy=false;}},
 'open-trash':()=>storage.api('open-trash',{}),
 'export-ledger':async()=>{const rows=[['Fecha','Tipo','Estado','Referencia','Moneda','Importe','Costo estimado'],...S().ledger.map(t=>[t.date,({sale:'Venta',purchase:'Compra',production:'Producción',print:'Impresión',adjustment:'Ajuste'})[t.type],t.voided?'Anulado':'Vigente',t.note,t.currency,t.total,t.cost])];const cell=v=>'"'+String(v??'').replace(/^[=+@-]/,"'"+'$&').replaceAll('"','""')+'"';await storage.download(new Blob(['\uFEFF'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'3D-Woods-movimientos.csv');}
 };
 async function change(el){
 if(el.id==='purchase-item'){const [kind,id]=el.value.split(':');purchaseDialog(kind,id);return true;}
 if(el.id==='sale-reserve'){ui.saleReserve=el.checked;ui.saleNote=value('sale-note');showSale();return true;}
 if(el.dataset.salePrice!=null){if(!el.checkValidity())throw Error('Revisa el precio de venta.');ui.cart[+el.dataset.salePrice].unitPrice=+el.value;ui.saleNote=value('sale-note');showSale();return true;}
 if(el.id==='sale-note'){ui.saleNote=el.value;return true;}
 if(el.dataset.connection){if(el.type==='number'&&!el.checkValidity())throw Error('Revisa el puerto de conexión.');const p=S().printers.find(p=>p.id===S().activePrinterId);p[el.dataset.connection]=el.type==='number'?+el.value:el.value.trim();persist();render();probe();return true;}
 if(el.id==='object-material'){if(!el.value)return true;const o=c.object();for(const p of o.parts){p.matId=el.value;p.grams=null;p.minutes=null;}o.material=el.value;o.gcode=null;c.box().thumbnail=null;persist();render();toast('Material cambiado. Vuelve a laminar para actualizar consumo y tiempo.');return true;}
 if(el.id==='bed-part'){ui.bedPart=el.value;ui.bedPage=1;render();return true;}
 if(el.id==='bed-page'){if(el.checkValidity()){ui.bedPage=+el.value;render();}return true;}
 return false;
 }
 return {actions,change,probe,isBusy:()=>transactionBusy};
}
